'use strict';
let state=null, user=null, csrf='', page='overview', authMode='login', teamFilter='', searchText='', onlyMine=false;
let mapMode='graph', proposalKind='transfer', factDraft=null, datasetTarget='', drag=null, suppressClickUntil=0;
let graphNodes=[], graphEdges=[], graphView=[0,0,1000,650];
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const fmt=(v,d=1)=>v==null?'—':Number(v).toLocaleString('ru-RU',{maximumFractionDigits:d});
const pct=v=>v==null?'Не рассчитано':fmt(v,0)+'%';
const plural=(n,one,few,many)=>{const a=Math.abs(n)%100,b=a%10;return a>=11&&a<=14?many:b===1?one:b>=2&&b<=4?few:many};
const isAdmin=()=>user?.role==='admin';
const fullHours=()=>state?.config?.hours_per_sprint??80;
const quarter=()=>state?.config?.sprints??6,horizon=()=>state?.config?.horizon??12;
const prefs={get(k){try{return localStorage.getItem(k)}catch{return null}},set(k,v){try{localStorage.setItem(k,v)}catch{}}};
let theme=prefs.get('orbita-theme')||(window.matchMedia?.('(prefers-color-scheme: dark)').matches?'dark':'light');
document.documentElement.dataset.theme=theme;
const statusNames={ToDo:'Не начата',InProgress:'В работе',Done:'Завершена'};
const planNames={done:'Факт',planned:'В квартале',beyond:'За кварталом',blocked:'Нужен ресурс',partial:'Часть вне горизонта'};
const badge=(label,tone='')=>`<span class="badge ${tone}">${esc(label)}</span>`;
const planBadge=e=>badge(planNames[e.status]||e.status,({done:'green',planned:'purple',blocked:'red',beyond:'orange',partial:'orange'})[e.status]);
const endText=e=>e.status==='done'?(e.end?`Завершено в С${e.end}`:'Завершено ранее'):e.end?`Спринт ${e.end}`:'Срок не определён';
const goalsInQuarter=()=>(state.initiatives||[]).filter(i=>i.forecast_in_quarter).length;
const decisionNames={include:'В квартал',groundwork:'Задел: цель не завершится в квартале',postpone:'Перенести на следующий квартал',cancel:'Отменить или пересмотреть'};
const ownTasks=()=>state.tasks.filter(t=>t.team===user.team);
const pendingTasks=()=>ownTasks().filter(t=>t.status!=='Done');
const personLabel=p=>p.name&&(p.registered||p.name!==p.id)?p.name:`${p.id} · ${p.roles.join(', ')||'Роль не указана'}`;
const personName=id=>{const p=state.people.find(p=>p.id===id);return p?personLabel(p):id};
const shortLabel=(text,limit)=>text.length>limit?text.slice(0,limit-1)+'…':text;
const taskAssignees=t=>[...new Set([...Object.values(t.manual_assignments||{}),...t.entry.fragments.flatMap(f=>f.assignments.map(a=>a.engineer))])];
const taskFragments=t=>[...(t.history||[]),...t.entry.fragments].sort((a,b)=>a.sprint-b.sprint);
const teamOptions=(value='',all=false)=>(all?'<option value="">Все команды</option>':'')+state.teams.map(t=>`<option value="${esc(t)}" ${t===value?'selected':''}>${esc(t)}</option>`).join('');
const taskOptions=(list,selected='')=>list.map(t=>`<option value="${esc(t.id)}" ${t.id===selected?'selected':''}>№ ${esc(t.id)} — ${esc(t.title.slice(0,65))}</option>`).join('');
const head=(title,subtitle='',actions='')=>`<div class="page-heading"><div><h1>${esc(title)}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><div class="button-row">${actions}</div></div>`;
const empty=(title,message='')=>`<div class="empty"><h2>${esc(title)}</h2><p>${esc(message)}</p></div>`;
function toast(message,error=false){$('#toast').innerHTML=`<div class="toast-box ${error?'error':''}">${esc(message)}</div>`;setTimeout(()=>{$('#toast').innerHTML=''},error?10000:4500)}
// Точный расчёт плана занимает десятки секунд при изменении состава
// команды или состава работ. Без признака работы окно выглядит так,
// будто нажатие не сработало, поэтому показываем счётчик секунд.
// Задержка в 400 мс не даёт ему мигать на быстрых операциях: повторный
// расчёт тех же условий сервер берёт из кэша почти мгновенно.
let busyTimer=null,busyDelay=null,busyDepth=0;
function busyShow(started){
 const tick=()=>{const s=Math.round((Date.now()-started)/1000);
  $('#toast').innerHTML=`<div class="toast-box busy">Пересчитываю план… ${s} с<p class="small">Идёт точный расчёт: сроки, роли и риски</p></div>`};
 tick();
 if(typeof setInterval==='function')busyTimer=setInterval(tick,1000);
}
// Признак занятости не должен ронять страницу там, где часть окружения
// недоступна: разметку проверяют в песочнице без body и без таймеров.
const busyBody=on=>{try{on?document.body.setAttribute('aria-busy','true'):document.body.removeAttribute('aria-busy')}catch{}};
function busyStart(){
 busyDepth++;
 if(busyDepth>1)return;
 busyBody(true);
 const started=Date.now();
 busyDelay=typeof setTimeout==='function'?setTimeout(()=>busyShow(started),400):null;
}
function busyStop(){
 busyDepth=Math.max(0,busyDepth-1);
 if(busyDepth)return;
 if(busyDelay!==null)clearTimeout(busyDelay);
 if(busyTimer!==null&&typeof clearInterval==='function')clearInterval(busyTimer);
 busyTimer=null;busyDelay=null;
 busyBody(false);
 const box=$('#toast');
 if(box&&String(box.innerHTML).includes('toast-box busy'))box.innerHTML='';
}
async function api(path,data,raw=false,extraHeaders={}){
 const type=raw===true?'text/csv':raw||'application/json';
 const options=data===undefined?{}:{method:'POST',headers:{'Content-Type':type,'X-CSRF-Token':csrf,...extraHeaders},body:raw?data:JSON.stringify(data)};
 if(options.method)busyStart();
 try{
  const response=await fetch(path,{credentials:'same-origin',...options});
  const result=await response.json();
  if(!response.ok){if(response.status===401&&!path.startsWith('/api/auth/')){user=null;state=null;renderAuth()}throw new Error(result.error||'Не удалось выполнить действие')}
  return result;
 }finally{if(options.method)busyStop()}
}
function base(extra={}){return{revision:state.revision,project_id:state.project_id,...extra}}
async function refresh(){state=await api('/api/state');user=state.user;render()}
async function mutate(path,extra={},message='Сохранено. Прогноз и риски обновлены.'){state=await api(path,base(extra));user=state.user;factDraft=null;closeDialog();render();toast(message)}
function toggleTheme(){theme=theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;prefs.set('orbita-theme',theme);document.querySelectorAll('[data-action="theme"]').forEach(b=>{b.textContent=theme==='dark'?'Светлая тема':'Тёмная тема';b.setAttribute('aria-pressed',String(theme==='dark'))})}
function themeButton(){return `<button type="button" class="btn small" data-action="theme" aria-pressed="${theme==='dark'}">${theme==='dark'?'Светлая тема':'Тёмная тема'}</button>`}
function brand(){return '<button class="brand" type="button" data-page="overview" aria-label="Орбита — главная страница"><img src="/icon.svg" alt=""><span><strong>ОРБИТА</strong><small>Планы и команды</small></span></button>'}
function renderAuth(){
 $('#app').innerHTML=`<div class="auth-theme">${themeButton()}</div><main class="auth-page"><section class="auth-intro">${brand()}<h1>Команды, задачи<br>и общий план.</h1><p>Распределяйте работу, следите за рисками и согласовывайте помощь между командами.</p></section><section class="card auth-form"><div class="tabs"><button type="button" data-auth-mode="login" class="${authMode==='login'?'active':''}">Войти</button><button type="button" data-auth-mode="register" class="${authMode==='register'?'active':''}">Регистрация</button></div><h2>${authMode==='login'?'С возвращением':'Создать учётную запись'}</h2><form id="auth-form">${authMode==='register'?`<label for="reg-role">Ваша роль</label><select id="reg-role" name="role"><option value="member">Сотрудник команды</option><option value="admin">Глава команды</option></select><label for="reg-name">Имя и фамилия</label><input id="reg-name" name="name" required maxlength="100" autocomplete="name"><label for="reg-code">Код приглашения</label><input id="reg-code" name="code" required autocomplete="off"><p class="small muted">Сотруднику код выдаёт глава команды. Код главы находится в файле team_access.txt на компьютере, где запущен сервер.</p>`:''}<label for="auth-login">Логин</label><input id="auth-login" name="login" required minlength="3" maxlength="80" autocomplete="username"><label for="auth-password">Пароль</label><input id="auth-password" name="password" type="password" required ${authMode==='register'?'minlength="10"':''} maxlength="256" autocomplete="${authMode==='register'?'new-password':'current-password'}">${authMode==='register'?'<p class="small muted">От 10 до 256 символов, не только цифры и не ваш логин. Команда закреплена за приглашением.</p>':''}<button class="btn primary" type="submit">${authMode==='register'?'Зарегистрироваться':'Войти'}</button><div id="auth-error" role="alert"></div></form></section></main>`;
}
function navs(){return isAdmin()?[['overview','Обзор','○'],['plan','Задачи и спринты','≡'],['map','Звёздная карта','✦'],['facts','Факт и пересчёт','↗'],['team','Команда','◉'],['requests','Согласования','⇄']]:[['overview','Мои задачи','○'],['plan','План команды','≡'],['team','Команда','◉']]}
function render(){
 if(!state||!user)return renderAuth();
 if(!navs().some(n=>n[0]===page))page='overview';
 const pending=state.requests.filter(r=>r.status==='pending'&&(!r.approvals.includes(user.team)||r.stale)).length;
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<nav class="nav" aria-label="Основные разделы">${navs().map(([id,label,symbol])=>`<button type="button" data-page="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span class="nav-symbol" aria-hidden="true">${symbol}</span>${label}${id==='requests'&&pending?`<span class="nav-count">${pending}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><strong>${esc(user.name)}</strong><small>${isAdmin()?'Глава команды':'Сотрудник'}<br>${esc(user.team)}</small></div></aside><div class="workspace"><header class="topbar"><div class="title">${esc(user.team)} · ${isAdmin()?'Управление командой':'Рабочее пространство'}</div><div class="top-actions"><button type="button" class="btn small" data-action="refresh">Обновить</button><a class="btn small" href="/api/report.csv" download>Отчёт CSV</a>${themeButton()}<button type="button" class="btn small" data-action="logout">Выйти</button></div></header><main class="content" id="main">${renderPage()}<p class="footer">6 спринтов · 12 недель. SP команды и часы специалистов учитываются отдельно.</p></main></div></div>`;
}
function renderPage(){return ({overview,plan:planView,map:mapView,facts:factsView,team:teamView,requests:requestsView})[page]()}
function baselineNotice(){
 const progress=state.baseline_approval||{required:0,confirmed:0,heads:[],own_approved:false,stale:false};
 return `<section class="notice"><strong>Согласуйте исходный план перед вводом факта.</strong><p>Состав квартальных целей и плановые SP станут постоянной базой сравнения после согласия всех зарегистрированных глав.</p><p>Подтверждения: ${progress.confirmed} из ${progress.required}.</p>${progress.stale?'<p>План или состав глав изменился. Требуется согласие заново.</p>':''}<div class="submission-list">${progress.heads.map(h=>badge(h.team+' · '+(h.approved?'согласовано':'ожидается'),h.approved?'green':'')).join('')}</div><div class="button-row">${progress.own_approved?badge('Ваше согласие учтено. Ожидаем остальных глав.','green'):'<button class="btn primary" data-action="approve">Согласовать исходный план</button>'}</div></section>`;
}
function overview(){
 if(!isAdmin()){
  const mine=state.tasks.filter(t=>t.mine&&t.status!=='Done');
  return head('Мои задачи',`${esc(user.name)} · ${esc(user.team)}`)+`<div class="stats"><div class="card"><p class="stat-label">Назначено вам</p><div class="stat-value">${mine.length}</div><p>Незавершённые работы</p></div><div class="card"><p class="stat-label">Работы команды</p><div class="stat-value">${state.tasks.filter(t=>t.status!=='Done').length}</div><p>Доступны в плане команды</p></div></div><section class="card"><div class="card-head"><h2>Ваши назначения</h2><button class="btn small" data-page="plan">План команды</button></div>${mine.length?taskTable(mine,false):empty('Назначений пока нет','Глава команды назначает исполнителей с учётом ролей и доступных часов.')}</section>`;
 }
 const m=state.metrics, pending=state.tasks.filter(t=>t.status!=='Done'), planned=pending.filter(t=>t.entry.status==='planned');
 const risks=pending.filter(t=>['blocked','partial','beyond'].includes(t.entry.status));
 const rc=riskCounts(state.risks);
 return head('Обзор квартала',`${esc(state.dates[0].start)} — ${esc(state.dates[5].end)}. План, результаты и ограничения команд.`,`${user.org_replan?'<button class="btn" data-action="replan">Пересчитать прогноз</button>':''}<button class="btn primary" data-page="plan">Открыть план</button>`)+
 `<div class="stats"><div class="card"><p class="stat-label">Задачи в квартале</p><div class="stat-value">${planned.length} <small>/ ${pending.length}</small></div><p>Прогноз по незавершённым работам</p></div><div class="card"><p class="stat-label">Фактически завершено целей</p><div class="stat-value">${state.baseline?pct(m.actual_percent):'—'}</div><p>${state.baseline?`${m.actual_done} из ${m.goal_count} исходных целей`:'Факт появится после фиксации исходного плана'}</p></div><div class="card"><p class="stat-label">Прогноз завершения целей</p><div class="stat-value">${state.baseline?pct(m.forecast_percent):`${goalsInQuarter()} <small>/ ${state.initiatives.length}</small>`}</div><p>${state.baseline?`${m.forecast_done} из ${m.goal_count} исходных целей к концу квартала`:'Инициатив завершаются в квартале — прогноз до фиксации базы'}</p></div><div class="card"><p class="stat-label">Инициативы за кварталом</p><div class="stat-value">${rc.red}</div><p>Жёлтых рисков: ${rc.yellow} · оранжевых: ${rc.orange}</p></div></div>`+
 staleNotice()+(!state.baseline?baselineNotice():'')+
 `<div class="grid"><section class="card"><div class="card-head"><h2>Ресурс команд на спринт</h2>${badge('Запас 20%','purple')}</div>${Object.entries(state.resources).map(([team,r])=>`<div class="team-line"><span>${esc(team)}</span><div class="bar"><span style="width:${r.capacity/Math.max(...Object.values(state.resources).map(x=>x.capacity),1)*100}%"></span></div><strong>${fmt(r.capacity)} SP</strong></div>`).join('')}<p class="small muted">Средняя фактическая производительность × 0,8. Назначения дополнительно ограничены часами и компетенциями.</p></section><section class="card"><div class="card-head"><div><h2>Риски плана</h2><p>Красный — инициатива не успевает в квартал. Жёлтый — сдвиг против исходного плана: цепочка зависимых задач или цель без запаса. Оранжевый — дефицит специалистов на следующий спринт.</p></div><button class="text-button" data-page="plan">Все задачи</button></div>${riskListMarkup(state.risks)}${risks.length?`<details><summary>Задачи за кварталом или без ресурса (${risks.length})</summary><ul class="risk-list">${risks.map(t=>`<li><button class="text-button" data-task="${esc(t.id)}">${esc(t.id)}</button> ${planBadge(t.entry)}<p>${esc(t.entry.reasons[0]||'Уточните ресурсы')}</p></li>`).join('')}</ul></details>`:''}</section></div>`+analysisMarkup()+reviewsMarkup(1)+
 `<section class="card"><div class="card-head"><h2>План и факт спринтов</h2><button class="text-button" data-page="facts">Внести факт</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Спринт</th><th>План исходной базы, SP</th><th>Зачтено по факту, SP</th><th>Выполнение</th><th>Заявлено командами, SP</th></tr></thead><tbody>${m.sprints.map(s=>`<tr><td>${s.sprint}</td><td>${state.baseline?fmt(s.planned):'—'}</td><td>${fmt(s.actual)}</td><td>${pct(s.percent)}</td><td>${fmt(s.reported)}</td></tr>`).join('')}</tbody></table></div><p class="small muted">Зачёт — по потраченным часам (не больше 90 % до закрытия задачи) и остатку закрытых задач, как в ядре. Заявленные SP обновляют производительность команд и в процент не входят.</p><details><summary>Качество исходных данных (${state.warnings.length})</summary><p class="small muted">Расхождения исходного Excel показаны отдельно от текущих рисков плана. Роли, добавленные главой, учитываются в текущем расчёте.</p><ul class="risk-list">${state.warnings.map(w=>`<li><strong>${esc(w.entity)}</strong><p>${esc(w.message)}</p></li>`).join('')}</ul></details><details><summary>История изменений</summary><ul class="risk-list">${state.versions.map(v=>`<li><strong>${esc(v.label)}</strong><p>${esc(new Date(v.created).toLocaleString('ru-RU'))}</p></li>`).join('')}</ul></details></section>`;
}
function filteredTasks(){return state.tasks.filter(t=>(!teamFilter||t.team===teamFilter)&&(!onlyMine||t.mine)&&`${t.id} ${t.title} ${t.initiative}`.toLowerCase().includes(searchText.toLowerCase()))}
function taskTable(rows,timeline=true){return `<div class="table-wrap"><table class="table ${timeline?'timeline':''}"><thead><tr><th>Задача <span class="th-hint">номер · название</span></th><th>Команда</th><th>Статус</th>${timeline?Array.from({length:6},(_,i)=>`<th title="Спринт ${i+1}">С${i+1}</th>`).join(''):'<th>Исполнители</th>'}<th>Прогноз</th></tr></thead><tbody>${rows.map(t=>`<tr><td class="task-title"><button class="text-button mono" data-task="${esc(t.id)}">${esc(t.id)}</button><small>${esc(t.title)}</small><small>Инициатива ${esc(t.initiative)} · ${fmt(t.remaining_sp)} SP осталось</small></td><td>${esc(t.team)}</td><td>${badge(statusNames[t.status],t.status==='Done'?'green':'')}</td>${timeline?Array.from({length:6},(_,i)=>{const f=taskFragments(t).find(f=>f.sprint===i+1),closed=i+1<=state.cutoff;return `<td>${f?`<button class="sprint-block" data-task="${esc(t.id)}" aria-label="${esc(t.id)}, спринт ${i+1}, ${fmt(f.sp)} SP${closed?', архив плана':''}">${fmt(f.sp)} SP${closed?'<small class="archive-label">Архив плана</small>':''}</button>`:closed?'Закрыт':'—'}</td>`}).join(''):`<td>${esc(taskAssignees(t).map(personName).join(', ')||'Не назначены')}</td>`}<td>${planBadge(t.entry)}<p class="small muted">${esc(endText(t.entry))}</p>${t.entry.decision==='groundwork'?'<p class="small muted">Задел: цель в квартале не завершится</p>':''}</td></tr>`).join('')||'<tr><td colspan="10">Задачи не найдены</td></tr>'}</tbody></table></div>`}
// Пояснения к кодам: что за набор символов у задачи, инициативы и сотрудника.
const codeHint={task:id=>`Номер задачи ${id}: код системы-заказчика и порядковый номер в трекере`,person:id=>`Табельный номер сотрудника: ${id}`};
function glossary(){return `<details class="glossary"><summary>Что означают коды</summary><dl>
<dt><span class="mono">ONK-2475</span>, <span class="mono">SRV-4011</span></dt><dd>Номер задачи из трекера: буквы — код системы или проекта, цифры — порядковый номер.</dd>
<dt><span class="mono">TASK-1A2B3C4D</span></dt><dd>Задача, добавленная в сервисе без собственного номера: код выдан автоматически.</dd>
<dt><span class="mono">PRODF-7120</span></dt><dd>Номер бизнес-инициативы. Инициатива считается выполненной, когда закрыты все её задачи.</dd>
<dt><span class="mono">ENG-401</span></dt><dd>Табельный номер сотрудника из профилей инженеров. У сотрудников, добавленных в сервисе, — <span class="mono">ENG-</span> и восемь символов.</dd>
<dt><span class="mono">Team-L</span></dt><dd>Код команды.</dd>
<dt>С1–С6, С7–С12</dt><dd>Спринты по две недели: С1–С6 — квартал, С7–С12 — прогноз за кварталом.</dd>
<dt>SP</dt><dd>Story Points — оценка объёма задачи в очках; ёмкость команды — средняя фактическая производительность × 0,8.</dd>
<dt>BF</dt><dd>Bus Factor — сколько людей владеют технологией. BF = 1: работа встанет без одного человека.</dd>
</dl></details>`}
document.addEventListener('mouseover',event=>{const el=event.target.closest?.('[data-task],[data-person]');if(!el||el.title)return;el.title=el.dataset.task?codeHint.task(el.dataset.task):codeHint.person(el.dataset.person)});
