function editRole(t,role,hours){return `<div class="role-row" data-role-row><div class="field"><label>Роль</label><input data-role value="${esc(role)}" readonly></div><div class="field"><label>Остаток, ч</label><input data-hours type="number" min="0" step="0.1" value="${hours}" required></div><div class="field assignee-field"><label>Исполнитель</label><select data-assignee><option value="">Автоматически</option>${eligiblePeople(t,role).map(p=>`<option value="${esc(p.id)}" ${t.manual_assignments?.[role]===p.id?'selected':''}>${esc(personLabel(p))}</option>`).join('')}</select></div><div class="field role-skills"><label>Обязательные навыки (через запятую)</label><input data-skills value="${esc((t.required_skills?.[role]||[]).join(', '))}" placeholder="Если требования подтверждены"></div></div>`}
function taskDialog(id){
 const t=state.tasks.find(t=>t.id===id);if(!t)return;const e=t.entry;
 const preds=state.edges.filter(e=>e[1]===id).map(e=>e[0]);const successors=state.edges.filter(e=>e[0]===id).map(e=>e[1]);
 const editable=isAdmin()&&t.team===user.team&&t.status!=='Done';
 const hours=Object.keys(t.remaining_hours).length?t.remaining_hours:t.hours;
 showDialog(drawerHead('Задача '+t.id,t.title)+`<p class="small muted code-note">${esc(t.id)} — номер задачи в трекере · входит в инициативу ${esc(t.initiative)}</p>${badge(t.team)} ${badge(statusNames[t.status])} ${planBadge(e)}<div class="summary"><div><small>Остаток SP</small><strong>${fmt(t.remaining_sp)}</strong></div><div><small>Остаток часов</small><strong>${fmt(Object.values(t.remaining_hours).reduce((s,h)=>s+h,0))}</strong></div><div><small>Завершение</small><strong>${e.end==null?'—':e.end===0?'Ранее':`С${e.end}`}</strong></div></div><h3>Почему получился такой план</h3>${e.decision&&e.status!=='done'?`<p>${badge(decisionNames[e.decision]||e.decision,({include:'green',groundwork:'orange',postpone:'orange',cancel:'red'})[e.decision])}</p>`:''}<ul class="risk-list">${e.reasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>${taskAssignees(t).length?`<p class="small muted">Текущие исполнители: ${esc(taskAssignees(t).map(personName).join(', '))}</p>`:''}<details><summary>Назначения по спринтам</summary><div class="table-wrap"><table class="table"><thead><tr><th>Спринт</th><th>Сотрудник</th><th>Роль</th><th>Часы</th></tr></thead><tbody>${taskFragments(t).flatMap(f=>f.assignments.map(a=>`<tr><td>${f.sprint}${f.sprint<=state.cutoff?' · архив плана':''}</td><td>${esc(personName(a.engineer))}</td><td>${esc(a.role)}</td><td>${fmt(a.hours)}</td></tr>`)).join('')||'<tr><td colspan="4">Нет доступных назначений</td></tr>'}</tbody></table></div></details>${taskFactsMarkup(t)}<details><summary>Цепочка зависимостей</summary><p class="small muted">До этой задачи: ${preds.length?preds.map(p=>`<button class="text-button" data-task="${esc(p)}">${esc(p)}</button>`).join(', '):'нет предшественников'}</p><p class="small muted">После этой задачи: ${successors.length?successors.map(p=>`<button class="text-button" data-task="${esc(p)}">${esc(p)}</button>`).join(', '):'нет зависимых задач'}</p></details>${editable?`<details open><summary>Ручное управление</summary><form id="task-form" data-task-id="${esc(id)}"><div class="form-grid"><div class="field"><label for="task-priority">Приоритет</label><input id="task-priority" name="priority" type="number" min="0" step="0.1" value="${t.priority}" required></div><div class="field"><label for="task-sp">Остаток SP</label><input id="task-sp" name="remaining_sp" type="number" min="0.1" step="0.1" value="${t.remaining_sp}" required></div><div class="field"><label for="task-start">Начать не раньше</label><select id="task-start" name="not_before">${state.dates.filter(d=>d.number>state.cutoff).map(d=>`<option value="${d.number}" ${Math.max(t.not_before||1,state.cutoff+1)===d.number?'selected':''}>Спринт ${d.number}${d.number>6?' · за кварталом':''}</option>`).join('')}</select></div></div><div class="spacer"></div><h3>Часы и исполнители по ролям</h3><div id="task-roles">${Object.entries(hours).map(([r,h])=>editRole(t,r,h)).join('')}</div><div id="task-preview" class="preview-result" aria-live="polite"></div><div class="form-actions"><button class="btn" type="button" data-action="task-preview">Проверить риски</button><button class="btn primary" type="submit">Сохранить и пересчитать</button></div></form></details><div class="form-actions"><button class="btn" data-transfer-task="${esc(id)}">Передать другой команде</button></div>`:''}`);
}
const dayText=d=>new Date(d+'T00:00:00').toLocaleDateString('ru-RU');
const lostTotal=a=>Object.values(a.lost||{}).reduce((sum,h)=>sum+h,0);
function absenceItem(a,canEdit,withName=false){return `<li>${badge(a.reason,a.reason==='Болезнь'?'red':'orange')} ${withName?`<button class="text-button" data-person="${esc(a.engineer)}">${esc(personName(a.engineer))}</button> · `:''}${esc(dayText(a.start))} — ${esc(dayText(a.end))} · −${fmt(lostTotal(a))} ч<p>${Object.entries(a.lost||{}).map(([s,h])=>`спринт ${s}: −${fmt(h)} ч`).join(', ')||'Рабочих дней в горизонте нет'}${a.comment?' · '+esc(a.comment):''}</p>${canEdit?`<button class="btn small danger" data-absence-remove="${esc(a.id)}">Отменить и пересчитать</button>`:''}</li>`}
function absenceMarkup(p){const list=(state.absences||[]).filter(a=>a.engineer===p.id),canEdit=isAdmin()&&p.allocations[user.team]>0,first=state.dates.find(d=>d.number===state.cutoff+1);
 return `<div class="spacer"></div><h3>Отсутствия</h3>${list.length?`<ul class="risk-list">${list.map(a=>absenceItem(a,canEdit)).join('')}</ul>`:'<p class="muted small">Отпусков, больничных и обучения не отмечено.</p>'}${canEdit&&first?`<details><summary>Отметить отпуск, болезнь или обучение</summary><form id="absence-form" data-person="${esc(p.id)}"><div class="form-grid"><div class="field"><label for="absence-start">С</label><input id="absence-start" name="start" type="date" min="${first.start}" value="${first.start}" required></div><div class="field"><label for="absence-end">По (включительно)</label><input id="absence-end" name="end" type="date" min="${first.start}" value="${first.start}" required></div><div class="field"><label for="absence-reason">Причина</label><select id="absence-reason" name="reason">${(state.absence_reasons||[]).map(r=>`<option>${esc(r)}</option>`).join('')}</select></div><div class="field"><label for="absence-comment">Комментарий</label><input id="absence-comment" name="comment" maxlength="300"></div></div><p class="small muted">Спринт — 10 рабочих дней: неделя отсутствия снимает половину часов сотрудника в спринте, день — десятую часть. ${Object.keys(p.allocations).length>1?'Сотрудник работает в нескольких командах — часы уменьшатся во всех. ':''}План пересчитается сразу после сохранения.</p><div id="absence-preview" class="preview-result" aria-live="polite"></div><div class="form-actions"><button class="btn" type="button" data-action="absence-preview">Проверить риски</button><button class="btn primary" type="submit">Сохранить и пересчитать</button></div></form></details>`:''}`}
function absencePayload(){const f=$('#absence-form'),v=formValues(f);return {engineer_id:f.dataset.person,start:v.start,end:v.end,reason:v.reason,comment:v.comment}}
function teamAbsences(){const people=new Set(state.people.filter(p=>p.allocations[user.team]>0).map(p=>p.id)),list=(state.absences||[]).filter(a=>people.has(a.engineer));
 return `<section class="card"><div class="card-head"><div><h2>Отсутствия в команде</h2><p>Отпуск, болезнь и обучение уменьшают часы сотрудника в затронутых спринтах; план пересчитывается сразу. Отметить отсутствие — в карточке сотрудника.</p></div></div>${list.length?`<ul class="risk-list">${list.map(a=>absenceItem(a,isAdmin(),true)).join('')}</ul>`:'<p class="muted small">Отсутствий не отмечено.</p>'}</section>`}
function personDialog(id){const p=state.people.find(p=>p.id===id);if(!p)return;const tasks=state.tasks.filter(t=>taskAssignees(t).includes(id));showDialog(drawerHead(personLabel(p),'Табельный номер '+p.id)+`${badge(p.grade)}<p>${esc(p.roles.join(', '))}</p>${singleRoleNotice(p)}${isAdmin()?`<div class="button-row"><button class="btn small" data-whatif="${esc(p.id)}">Что будет без сотрудника</button></div>`:''}<div class="summary"><div><small>Доступно в ближайшем спринте</small><strong>${fmt(p.available)} ч</strong></div><div><small>Назначено</small><strong>${fmt(p.used)} ч</strong></div></div><h3>Компетенции</h3><div class="pill-list">${p.skills.map(s=>badge(s,'purple')).join('')}</div><div class="spacer"></div><h3>Распределение между командами</h3><ul class="risk-list">${Object.entries(p.allocations).map(([t,r])=>`<li>${esc(t)} · ${fmt(r*100)}% · ${fmt(r*fullHours())} базовых часов</li>`).join('')}</ul><details><summary>Назначенные задачи (${tasks.length})</summary><ul class="risk-list">${tasks.map(t=>`<li><button class="text-button" data-task="${esc(t.id)}">${esc(t.id)}</button> ${esc(t.title)}</li>`).join('')}</ul></details>${absenceMarkup(p)}${isAdmin()&&Object.keys(p.allocations).length===1&&p.allocations[user.team]?`<details><summary>Доступность в следующем спринте</summary><form id="availability-form" data-person="${esc(id)}"><label for="available-hours">Часы в спринте ${state.cutoff+1}</label><input id="available-hours" name="hours" type="number" min="0" max="${fullHours()*p.allocations[user.team]}" step="0.1" value="${p.available}" required><div class="form-actions"><button class="btn primary" type="submit">Сохранить доступность</button></div></form></details>`:''}`)}
function graphBounds(n,x=n.x,y=n.y){
 const team=n.type==='team',half=Math.max(team?44:24,n.label.length*4.2+8,(n.detail?.length||0)*3.2+8);
 return {left:x-half,right:x+half,top:y-(team?42:20),bottom:y+(team?64:n.detail?52:36)};
}
function layoutGraph(nodes){
 // Команды остаются опорными точками. Сотруднику выбираем ближайшее
 // свободное место с учётом круга и подписи, прежде всего общим людям.
 const placed=nodes.filter(n=>n.type==='team').map(n=>graphBounds(n));
 const people=nodes.filter(n=>n.type==='person').sort((a,b)=>Number(b.shared)-Number(a.shared)||a.id.localeCompare(b.id));
 const overlap=(a,b)=>Math.max(0,Math.min(a.right,b.right)-Math.max(a.left,b.left))*Math.max(0,Math.min(a.bottom,b.bottom)-Math.max(a.top,b.top));
 for(const n of people){
  const bounds=graphBounds(n,0,0),minX=12-bounds.left,maxX=988-bounds.right,minY=12-bounds.top,maxY=638-bounds.bottom;
  let best=null;
  function consider(x,y){
   const box=graphBounds(n,x,y),area=placed.reduce((sum,p)=>sum+overlap(box,p),0),distance=(x-n.x)**2+(y-n.y)**2;
   if(!best||area<best.area||(area===best.area&&distance<best.distance))best={x,y,area,distance,box};
  }
  consider(Math.max(minX,Math.min(maxX,n.x)),Math.max(minY,Math.min(maxY,n.y)));
  if(best.area){
   for(let y=minY;y<=maxY;y+=12)for(let x=minX;x<=maxX;x+=12)consider(x,y);
  }
  n.x=best.x;n.y=best.y;placed.push(best.box);
 }
}
function graphMarkup(){
 let saved={};try{saved=JSON.parse(prefs.get('orbita-map-'+state.project_id)||'{}')}catch{}
 const teams=state.teams,centers={};
 teams.forEach((team,i)=>{const angle=-Math.PI/2+i*Math.PI*2/teams.length;centers[team]={x:500+310*Math.cos(angle),y:320+198*Math.sin(angle)}});
 graphNodes=teams.map(t=>({id:'t:'+t,label:t,type:'team',key:t,...centers[t]}));graphEdges=[];
 state.people.forEach(p=>{
  const links=Object.keys(p.allocations).filter(t=>p.allocations[t]>0&&centers[t]);
  let x=0,y=0;
  links.forEach(t=>{const members=state.people.filter(e=>e.allocations[t]>0),i=members.findIndex(e=>e.id===p.id),angle=i*Math.PI*2/members.length+.45;x+=centers[t].x+88*Math.cos(angle);y+=centers[t].y+75*Math.sin(angle)});
  const role=p.roles.join(', ')||'Роль не указана';
  graphNodes.push({id:'p:'+p.id,key:p.id,type:'person',label:shortLabel(p.name||p.id,22),detail:shortLabel(role,24),name:personLabel(p),critical:(p.single_roles||[]).length>0,description:[p.id,p.name!==p.id?p.name:'',role,(p.single_roles||[]).length?'единственный носитель роли: '+p.single_roles.join(', '):''].filter(Boolean).join(' · '),x:x/Math.max(links.length,1),y:y/Math.max(links.length,1),shared:links.length>1});
  links.forEach(t=>graphEdges.push({from:'t:'+t,to:'p:'+p.id}));
 });
 layoutGraph(graphNodes);
 // Сохранённые пользователем координаты имеют приоритет над автоподбором.
 graphNodes.forEach(n=>{const s=saved[n.id];if(s&&Number.isFinite(s.x)&&Number.isFinite(s.y)){n.x=s.x;n.y=s.y}});
 const nodes=new Map(graphNodes.map(n=>[n.id,n]));
 return `<svg class="star-map" id="star-map" viewBox="${graphView.join(' ')}" role="img" aria-label="Звёздная карта команд и сотрудников. Узлы можно перетаскивать или двигать стрелками клавиатуры."><title>Команды и сотрудники</title>${graphEdges.map(e=>`<line class="edge" data-from="${esc(e.from)}" data-to="${esc(e.to)}" x1="${nodes.get(e.from).x}" y1="${nodes.get(e.from).y}" x2="${nodes.get(e.to).x}" y2="${nodes.get(e.to).y}"></line>`).join('')}${graphNodes.map(n=>`<g data-node="${esc(n.id)}" data-${n.type}="${esc(n.key)}" transform="translate(${n.x},${n.y})" class="${n.shared?'shared':''} ${n.critical?'critical':''}" role="button" tabindex="0" aria-label="${esc(n.description||n.name||n.label)}. Перетащите для перемещения, Enter — подробности"><title>${esc(n.description||n.name||n.label)}</title><circle r="${n.type==='team'?34:12}" class="${n.type==='team'?'team-circle':'person-circle'}"></circle><text y="${n.type==='team'?55:28}" class="${n.type==='team'?'team-text':''}">${esc(n.label)}</text>${n.detail?`<text y="44" class="person-role">${esc(n.detail)}</text>`:''}</g>`).join('')}</svg>`;
}
function mapView(){
 if(!isAdmin())return '';
 const cells=state.skills.filter(c=>!teamFilter||c.team===teamFilter);
 return head('Звёздная карта','Зажмите узел и переместите его. Свободное поле можно тянуть для перемещения карты.','<button class="btn" data-action="reset-map">Сбросить расположение</button>')+`<section class="card"><div class="tabs"><button data-map-mode="graph" class="${mapMode==='graph'?'active':''}">Команды и люди</button><button data-map-mode="risks" class="${mapMode==='risks'?'active':''}">Риски компетенций</button></div>${mapMode==='graph'?`<div class="graph-wrap">${graphMarkup()}</div><div class="graph-key"><span>Большой узел — команда</span><span>Малый узел — сотрудник</span><span><i class="legend-circle"></i>Общий сотрудник нескольких команд</span><span><i class="legend-circle critical"></i>Единственный носитель роли</span></div>`:`${roleMapMarkup()}<div class="spacer"></div>${orgMapMarkup()}<div class="spacer"></div><h2>Технологии по командам</h2><div class="filters"><select id="team-filter" aria-label="Команда">${teamOptions(teamFilter,true)}</select></div><p class="small muted">Bus Factor (BF) — число уникальных носителей навыка в команде. При BF = 1 команда зависит от одного человека.</p><div class="table-wrap"><table class="table"><thead><tr><th>Команда</th><th>Компетенция</th><th>BF</th><th>Носители</th><th>Свободно часов</th><th>Связанные работы</th></tr></thead><tbody>${cells.sort((a,b)=>a.bf-b.bf).map(c=>`<tr><td>${esc(c.team)}</td><td>${esc(c.skill)}</td><td>${badge(c.bf,c.bf===1?'orange':'green')}</td><td>${c.holders.map(id=>`<button class="text-button" data-person="${esc(id)}">${esc(personName(id))}</button>`).join(', ')}</td><td>${fmt(c.free_hours)}</td><td>${c.related_tasks.slice(0,4).map(id=>`<button class="text-button" data-task="${esc(id)}">${esc(id)}</button>`).join(', ')||'—'}</td></tr>`).join('')}</tbody></table></div><p class="small muted">Связанные работы — задачи, которые носители ведут по текущему плану. Часы разных навыков одного человека нельзя складывать.</p>`}${bfMethod()}${glossary()}</section>`;
}
