function teamDialog(team){const people=state.people.filter(p=>p.allocations[team]>0),prof=(state.team_profiles||{})[team];
 showDialog(drawerHead(team,'Профиль команды')+`<div class="summary"><div><small>Ёмкость на спринт</small><strong>${fmt(state.resources[team]?.capacity)} SP</strong></div><div><small>По плану в ближайшем спринте</small><strong>${fmt(prof?.planned_sp)} SP</strong></div><div><small>Часы других команд в квартале</small><strong>${fmt(prof?.borrowed_hours,0)} ч</strong></div></div>${prof?.single?.length?`<div class="notice warning"><strong>Один носитель в команде</strong><p>${esc(prof.single.join(', '))}: без этого человека работы команды по роли перейдут к другим командам или встанут.</p></div>`:''}<h3>Состав</h3><ul class="risk-list">${people.map(p=>`<li><button class="text-button" data-person="${esc(p.id)}">${esc(personLabel(p))}</button><p>${esc(p.roles.join(', '))} · ${fmt(p.allocations[team]*fullHours())} базовых часов${(p.single_roles||[]).length?' · единственный носитель роли '+esc(p.single_roles.join(', ')):''}</p></li>`).join('')}</ul>${prof?`<h3>Покрытие ролей</h3><div class="table-wrap"><table class="table"><thead><tr><th>Роль</th><th>Свои носители</th><th>Своих часов в спринт</th><th>Нужно работам команды, ч</th></tr></thead><tbody>${prof.roles.map(r=>`<tr><td>${esc(r.role)}</td><td>${r.holders.map(id=>`<button class="text-button" data-person="${esc(id)}">${esc(id)}</button>`).join(', ')||badge(roleOutside(r.role),'orange')}</td><td class="num">${fmt(r.own_hours)}</td><td class="num">${fmt(r.demand_hours,0)}</td></tr>`).join('')}</tbody></table></div><p class="small muted">Роли без своих носителей команда берёт у других команд, а если роли нет ни у кого — у внешних исполнителей. Это видно в заимствованиях и в оранжевом риске «Помощь между командами».</p><details><summary>Открытые задачи (${prof.open_tasks.length})</summary><p>${prof.open_tasks.map(subjectLink).join(', ')}</p></details>`:''}`)}
function teamView(){const people=state.people.filter(p=>p.allocations[user.team]>0);return head('Команда',`${esc(user.team)} · ${people.length} сотрудников`,isAdmin()?'<button class="btn primary" data-action="new-employee">Добавить сотрудника</button>':'')+teamAbsences()+`<div class="member-grid">${people.map(p=>`<article class="person"><div class="avatar">${esc(p.name.split(/\s+/).map(w=>w[0]).slice(0,2).join(''))}</div><h3><button class="text-button" data-person="${esc(p.id)}">${esc(personLabel(p))}</button></h3><p class="small muted">Табельный номер ${esc(p.id)}</p><p>${esc(p.roles.join(', '))}</p><div class="pill-list">${p.skills.slice(0,4).map(s=>badge(s)).join('')}</div><p>${fmt(p.allocations[user.team]*fullHours())} базовых часов · ${esc(p.grade)}</p>${isAdmin()?`<div class="button-row"><button class="btn small" data-person="${esc(p.id)}">Профиль</button>${p.registered?badge('Зарегистрирован','green'):`<button class="btn small" data-invite="${esc(p.id)}">Пригласить</button>`}</div>`:''}</article>`).join('')}</div>${glossary()}`}
// Ключ роли — то же правило, что src/normalizer.role_key: без регистра,
// пробелов, «_», дефисов и точек. «Дев_опс» и «ДевОпс» — одна роль.
const roleKey=r=>String(r??'').replace(/[\s_\-‐-―.·]+/g,'').toLowerCase().replaceAll('ё','е');
function knownRoles(){return [...new Set(state.people.flatMap(p=>p.roles).concat(state.tasks.flatMap(t=>Object.keys(t.hours))))].sort((a,b)=>a.localeCompare(b,'ru'))}
function rolePicker(){return `<select data-role-select aria-label="Роль" required><option value="">Выберите роль</option>${knownRoles().map(r=>`<option value="${esc(r)}">${esc(r)}</option>`).join('')}<option value="__new">+ Новая роль…</option></select><input data-role-new maxlength="100" placeholder="Название новой роли" aria-label="Название новой роли" hidden>`}
function pickedRole(row){const select=row.querySelector('[data-role-select]');if(select.value!=='__new')return select.value;const typed=row.querySelector('[data-role-new]').value.trim().replace(/\s+/g,' ');return knownRoles().find(r=>roleKey(r)===roleKey(typed))||typed}
function employeeRoleRow(){return `<div class="role-row new" data-employee-role><div class="field"><label>Роль</label>${rolePicker()}</div><button class="btn small" data-action="remove-employee-role" type="button" aria-label="Удалить роль">×</button></div>`}
function newEmployeeDialog(){showDialog(drawerHead('Новый сотрудник',user.team)+`<form id="employee-form"><div class="form-grid"><div class="field full"><label for="employee-name">Имя и фамилия</label><input id="employee-name" name="name" required maxlength="100"></div><div class="field"><label for="employee-grade">Уровень</label><select id="employee-grade" name="grade"><option>Junior</option><option selected>Middle</option><option>Senior</option></select></div><div class="field"><label for="employee-rate">Доля занятости (1 = ${fmt(fullHours())} ч)</label><input id="employee-rate" name="capacity_rate" type="number" min="0.01" max="1" step="0.01" value="1" required></div><div class="field full"><label>Подтверждённые роли</label><p class="small muted">Выберите из ролей, которые уже есть в организации, или добавьте новую. Написание, отличающееся только регистром, пробелами или «_», будет сведено к существующей роли.</p><div id="employee-role-list">${employeeRoleRow()}</div><button class="btn small" type="button" data-action="add-employee-role">Добавить ещё роль</button></div><div class="field full"><label for="employee-skills">Компетенции (одна на строку)</label><textarea id="employee-skills" name="skills" rows="3" placeholder="Java\nSpring Boot"></textarea></div></div><div class="form-actions"><button class="btn primary" type="submit">Добавить сотрудника</button></div></form>`)}
function newRoleRow(){return `<div class="role-row new" data-new-role><div><label>Роль</label>${rolePicker()}</div><div><label>Часы</label><input data-hours type="number" min="0.1" step="0.1" required></div><button class="btn small" data-action="remove-role" type="button" aria-label="Удалить роль">×</button></div>`}
function newTaskDialog(){showDialog(drawerHead('Новая задача',user.team)+`<form id="new-task-form"><div class="form-grid"><div class="field full"><label for="new-title">Название</label><input id="new-title" name="title" maxlength="300" required></div><div class="field"><label for="new-id">Код задачи (можно не заполнять)</label><input id="new-id" name="task_id" maxlength="60" placeholder="Автоматически"></div><div class="field"><label for="new-initiative">Инициатива</label><input id="new-initiative" name="initiative" list="initiatives" required maxlength="80"><datalist id="initiatives">${[...new Set(state.tasks.map(t=>t.initiative))].map(i=>`<option value="${esc(i)}">`).join('')}</datalist></div><div class="field"><label for="new-sp">Story Points</label><input id="new-sp" name="sp" type="number" min="0.1" step="0.1" required></div><div class="field"><label for="new-priority">Приоритет</label><input id="new-priority" name="priority" type="number" min="0" step="0.1" value="50" required></div><div class="field full"><label for="new-deps">Зависит от задач (коды через запятую)</label><input id="new-deps" name="predecessors" placeholder="Например, SRV-4011, MP-101"></div></div><div class="spacer"></div><h3>Потребность в специалистах</h3><div id="new-roles">${newRoleRow()}</div><button class="btn small" type="button" data-action="add-role">Добавить роль</button><div class="form-actions"><button class="btn primary" type="submit">Добавить и пересчитать</button></div></form>`)}
const sourceNames={dataset:['из датасета','green'],report:['из отчёта','purple'],none:['нет данных','red']};
function datasetSummary(d){const s=d.summary,list=ids=>ids.map(subjectLink).join(', ');
 return `<p class="small muted">Файл загрузил(а) ${esc(d.uploaded_by)} · ${esc(new Date(d.uploaded_at).toLocaleString('ru-RU'))}</p><ul class="risk-list">
<li>Закрыто задач: <strong>${s.closed.length}</strong>${s.closed.length?' — '+list(s.closed):''}</li>
<li>Изменился статус: <strong>${s.status_changes.length}</strong>${s.status_changes.length?`<p>${s.status_changes.map(c=>`${esc(c.task_id)}: ${esc(statusNames[c.before]||c.before)} → ${esc(statusNames[c.after]||c.after)}`).join('; ')}</p>`:''}</li>
<li>Потрачено часов за спринт: <strong>${fmt(s.spent_hours)}</strong></li>
<li>SP команд из Team_history: ${Object.keys(s.velocity).length?Object.entries(s.velocity).map(([t,v])=>`${esc(t)} ${fmt(v)}`).join(' · '):'новых строк нет — SP возьмутся из отчётов команд'}</li>
${s.new_tasks.length?`<li>Новые задачи: ${list(s.new_tasks)}</li>`:''}${s.new_people.length?`<li>Новые сотрудники: ${s.new_people.map(esc).join(', ')}</li>`:''}
${s.missing_tasks.length?`<li>Нет в датасете, остаются в плане без изменений: ${list(s.missing_tasks)}</li>`:''}</ul>`}
function readinessMarkup(r){const counts=r.task_sources||{};
 return `<h3>Откуда возьмутся данные</h3><div class="submission-list">${Object.entries(r.team_sources).map(([t,src])=>badge(t+' · SP '+sourceNames[src][0],sourceNames[src][1])).join('')}</div><p class="small muted">Задачи: ${Object.entries(counts).map(([src,n])=>`${sourceNames[src][0]} — ${n}`).join(', ')||'нет открытых задач'}. Датасет — официальный срез: при расхождении берётся он; отчёт команды используется для задач, которых нет в датасете, и для SP, если в Team_history нет новой строки.</p>${r.missing_teams.length?`<div class="notice warning">Нет выполненных SP для команд: ${esc(r.missing_teams.join(', '))}. Нужна новая строка Team_history в датасете или отчёт главы.</div>`:''}${r.discrepancies.length?`<details><summary>Расхождения датасета с отчётами команд (${r.discrepancies.length})</summary><ul class="risk-list">${r.discrepancies.map(d=>`<li>${subjectLink(d.task_id)} · ${esc(d.team)}<p>${esc(d.text)}</p></li>`).join('')}</ul></details>`:''}${r.corrections.length?`<details><summary>Часов в датасете меньше, чем уже учтено (${r.corrections.length})</summary><p class="small muted">Такие поправки относятся к прошлому спринту: исправьте его отдельной загрузкой.</p><ul class="risk-list">${r.corrections.map(c=>`<li>${esc(c)}</li>`).join('')}</ul></details>`:''}${r.untouched.length?`<p class="small muted">Без данных в этом спринте, остаются как были: ${r.untouched.map(subjectLink).join(', ')}</p>`:''}`}
function sprintBlock(r,correction=false){const can=user.org_replan;
 return `${r.dataset?datasetSummary(r.dataset):`<p class="muted">Обновлённый датасет за спринт ${r.sprint} ещё не загружен.</p>`}${readinessMarkup(r)}${can?`<div class="form-actions"><button class="btn" data-action="upload-dataset" data-sprint="${r.sprint}">${r.dataset?'Заменить датасет':'Загрузить обновлённый датасет'}</button><button class="btn primary" data-action="close-sprint" data-sprint="${r.sprint}" ${r.ready?'':'disabled'}>${correction?`Пересчитать спринт ${r.sprint} заново`:`Итоговый пересчёт спринта ${r.sprint}`}</button></div>`:'<p class="small muted">Датасет загружает и итоговый пересчёт запускает глава с правом пересчёта организации.</p>'}`}
function sprintDataCard(){const sd=state.sprint_data,cur=sd?.current;if(!cur)return '';
 const fix=state.cutoff>=1&&user.org_replan?`<details ${sd.correction?'open':''}><summary>Исправить закрытый спринт ${state.cutoff}</summary><p class="small muted">Загрузите исправленный датасет за спринт ${state.cutoff}. Спринт не удаляется: его факт заменяется исправленным, план пересчитывается, исходная база не меняется.</p>${sd.correction?sprintBlock(sd.correction,true):`<div class="form-actions"><button class="btn" data-action="upload-dataset" data-sprint="${state.cutoff}">Загрузить исправленный датасет</button></div>`}</details>`:'';
 return `<section class="card"><div class="card-head"><div><h2>Данные спринта ${cur.sprint}</h2><p>Обновлённый датасет и отчёты команд сохраняются без пересчёта. План пересчитывается одной кнопкой, когда данные собраны.</p></div></div>${sprintBlock(cur)}${fix}</section>`}
function reviewsMarkup(limit=99){const list=Object.values(state.reviews||{}).sort((a,b)=>b.sprint-a.sprint).slice(0,limit);if(!list.length)return '';
 return `<section class="card"><h2>Итоги спринтов</h2><p class="small muted">Какие отклонения спринта вызвали изменения плана и какие цели оказались под угрозой.</p>${list.map((r,i)=>`<details ${i===0?'open':''}><summary>Спринт ${r.sprint}: ${r.deviations.length} ${plural(r.deviations.length,'отклонение','отклонения','отклонений')}${r.goals_lost.length?` · ${r.goals_lost.length} ${plural(r.goals_lost.length,'цель ушла','цели ушли','целей ушли')} за квартал`:''}</summary>${r.goals_lost.length?`<div class="notice warning">Ушли за квартал: ${r.goals_lost.map(esc).join(', ')}</div>`:''}${r.goals_gained.length?`<p>Вернулись в квартал: ${r.goals_gained.map(esc).join(', ')}</p>`:''}<ul class="risk-list">${r.deviations.map(d=>{const next=(r.consequences||{})[d.task_id]||[];return `<li>${subjectLink(d.task_id)} · ${esc(d.team)}<p>${esc(d.text)}</p>${next.length?`<p class="small muted">Повлекло: ${next.map(x=>`${subjectLink(x.task_id)} (${x.before==null?'—':'С'+x.before} → ${x.after==null?'—':'С'+x.after})`).join(', ')}</p>`:''}</li>`}).join('')||'<li>План спринта выполнен без отклонений.</li>'}</ul>${r.capacity?.length?`<p class="small muted">Производительность команд после факта: ${esc(r.capacity.join('; '))}</p>`:''}${r.dataset?`<p class="small muted">Данные: датасет ${esc(r.dataset.uploaded_by)}, ${esc(new Date(r.dataset.uploaded_at).toLocaleString('ru-RU'))}.</p>`:''}</details>`).join('')}</section>`}
function staleNotice(){const s=state.plan_stale;if(!s)return '';
 return `<section class="notice warning"><strong>Данные обновлены, план не пересчитан.</strong><p>${esc(s.reason)} · ${esc(s.uploaded_by||'')}</p>${(s.notes||[]).map(n=>`<p>${esc(n)}</p>`).join('')}<div class="button-row">${user.org_replan?'<button class="btn primary" data-action="replan">Пересчитать план</button>':'<span class="small">Пересчёт запускает глава с правом пересчёта организации.</span>'}</div></section>`}
function initialDataCard(){if(!user.org_replan)return '';
 return `<section class="card"><h2>Исходный датасет</h2><p class="small muted">До фиксации исходного плана можно загрузить другой датасет в том же формате. Он заменит исходные данные; задачи и сотрудники, добавленные в сервисе, сохранятся. План пересчитается кнопкой «Пересчитать план».</p><div class="form-actions"><button class="btn" data-action="upload-dataset" data-sprint="">Загрузить исходный датасет</button></div></section>`}
function factValues(){return factDraft||(state.own_draft?.basis?state.own_draft:null)}
function factsView(){
 if(!isAdmin())return '';
 if(!state.baseline)return head('Факт и пересчёт')+staleNotice()+baselineNotice()+initialDataCard();
 if(state.cutoff>=quarter())return head('Квартал завершён','Результаты всех спринтов квартала сохранены.')+`<section class="card"><p>Фактически завершено ${state.metrics.actual_done} из ${state.metrics.goal_count} исходных целей.</p><div class="form-actions"><a class="btn primary" href="/api/report.csv" download>Скачать отчёт CSV</a></div></section>`+sprintDataCard()+reviewsMarkup();
 const draft=factValues(),sprint=state.cutoff+1,rows=pendingTasks();
 return head('Факт и пересчёт',`Спринт ${sprint} · ${esc(user.team)}. Отчёт команды можно менять до итогового пересчёта: сохранение план не пересчитывает.`,`<a class="btn" href="/api/facts/template.csv" download>Шаблон CSV</a><button class="btn" data-action="import-facts">Загрузить CSV</button>`)+
 sprintDataCard()+`<section class="card"><h2>Отчёты команд об итогах спринта</h2><div class="submission-list">${state.submissions.map(s=>badge(s.team+' · '+(s.valid?'сохранён':s.submitted?'устарел':'ожидается'),s.valid?'green':s.submitted?'orange':'')).join('')}</div><p class="small muted">Отчёт вносится в течение спринта и может меняться до итогового пересчёта. Загрузка CSV заполняет форму; сохранение выполняется кнопкой ниже.</p><p class="small muted">Остатки можно не заполнять: тогда остаток роли — прежний минус потраченные часы, а если часы кончились, а задача не закрыта, — 10 % сметы. Выполнение спринта засчитывается по потраченным часам и закрытым задачам; SP команды обновляют её производительность на следующие спринты.</p></section><section class="card"><form id="fact-form"><div class="fact-meta"><div class="field"><label for="team-sp">Фактически выполнено SP команды</label><input id="team-sp" name="achieved_sp" type="number" min="0" step="0.1" required value="${draft?.achieved_sp??''}" placeholder="Включая внеплановую работу"></div><div class="field"><label for="fact-note">Комментарий</label><input id="fact-note" name="note" maxlength="1000" value="${esc(draft?.note||'')}"></div></div><div class="spacer"></div><h2>Результаты задач</h2>${rows.map(t=>{
  const saved=draft?.tasks?.find(r=>r.task_id===t.id),status=saved?.status||t.status,remaining=t.remaining_hours,left=saved?.remaining_hours||{};
  const roles=[...new Set([...Object.keys(t.hours),...Object.keys(remaining),...Object.keys(left),...Object.keys(saved?.spent_hours||{})])];
  return `<div class="fact-task" data-fact-task="${esc(t.id)}"><div class="fact-main"><div><strong>${esc(t.id)}</strong><p>${esc(t.title)}</p></div><div><label>Статус</label><select data-status>${Object.entries(statusNames).map(([id,label])=>`<option value="${id}" ${status===id?'selected':''}>${label}</option>`).join('')}</select></div><div><label>Остаток SP</label><input data-remaining-sp type="number" min="0" step="0.1" value="${saved?.remaining_sp??''}" placeholder="по часам, сейчас ${fmt(t.remaining_sp)}" ${status==='Done'?'readonly':''}></div></div><details><summary>Часы по ролям (${roles.length})</summary><div class="fact-hours muted"><span>Роль</span><span>Осталось, ч</span><span>Потрачено, ч</span></div>${roles.map(role=>`<div class="fact-hours" data-fact-role="${esc(role)}"><span>${esc(role)}</span><input data-left type="number" min="0" step="0.1" value="${left[role]??''}" placeholder="${fmt(remaining[role]||0)} − потрачено" aria-label="${esc(role)}: остаток часов" ${status==='Done'?'readonly':''}><input data-spent type="number" min="0" step="0.1" value="${saved?.spent_hours?.[role]||0}" aria-label="${esc(role)}: потраченные часы" required></div>`).join('')}</details></div>`
 }).join('')||'<p class="muted">У команды нет незавершённых задач. Подтвердите фактически выполненные SP.</p>'}<div class="form-actions"><button class="btn primary" type="submit">Сохранить отчёт команды</button></div></form></section>${state.changes.length?`<section class="card"><h2>Последние изменения прогноза</h2>${changesMarkup(state.changes)}</section>`:''}`+reviewsMarkup();
}
const sprintText=v=>v==null?'—':'С'+v;
function changeSpan(c){return c.before.end===c.after.end&&c.before.start!==c.after.start?`начало ${sprintText(c.before.start)} → ${sprintText(c.after.start)}, завершение ${sprintText(c.after.end)}`:`${sprintText(c.before.end)} → ${sprintText(c.after.end)}`}
function changeLine(c){return `<li><button class="text-button" data-task="${esc(c.task_id)}">${esc(c.task_id)}</button> · ${changeSpan(c)}${c.after.status==='beyond'?' '+badge('за кварталом','orange'):''}<p>${esc(c.reason)}</p></li>`}
// Сдвиги сроков — главное; закрытые задачи и смена исполнителей без сдвига
// сроков свёрнуты, чтобы не заслонять причины сдвигов.
function changesMarkup(changes){
 if(!changes.length)return '<ul class="risk-list"><li>Сроки и назначения других задач не изменились.</li></ul>';
 const moved=changes.filter(c=>(c.kind||'schedule')==='schedule'),done=changes.filter(c=>c.kind==='done'),people=changes.filter(c=>c.kind==='assignments');
 return `${moved.length?`<ul class="risk-list">${moved.slice(0,30).map(changeLine).join('')}</ul>`:'<p class="muted">Сроки задач не сдвинулись.</p>'}${done.length?`<details><summary>Закрыты по факту (${done.length})</summary><p class="small">${done.map(c=>subjectLink(c.task_id)).join(', ')}</p></details>`:''}${people.length?`<details><summary>Срок прежний, изменились исполнители или объём по спринтам (${people.length})</summary><ul class="risk-list">${people.map(changeLine).join('')}</ul></details>`:''}`}
const riskNames={red:'Красный',yellow:'Жёлтый',orange:'Оранжевый'};
function subjectLink(id){return state.tasks.some(t=>t.id===id)?`<button class="text-button" data-task="${esc(id)}">${esc(id)}</button>`:`<strong>${esc(id)}</strong>`}
function riskItem(r){return `<li>${badge(riskNames[r.level]||r.level,r.level)} ${subjectLink(r.subject)}<p>${esc(r.text)}</p></li>`}
function riskListMarkup(risks,limit=8){if(!risks.length)return '<p class="muted">Рисков нет: инициативы завершаются в квартале, дефицита ролей на следующий спринт нет.</p>';return `<ul class="risk-list">${risks.slice(0,limit).map(riskItem).join('')}</ul>${risks.length>limit?`<details><summary>Все риски (${risks.length})</summary><ul class="risk-list">${risks.slice(limit).map(riskItem).join('')}</ul></details>`:''}`}
function simpleTable(heads,rows){return rows.length?`<div class="table-wrap"><table class="table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:'<p class="muted">Нет.</p>'}
function analysisMarkup(){const a=state.analysis||{},e=a.engines,bottlenecks=(a.bottlenecks||[]).slice().sort((x,y)=>x.sprint-y.sprint);
 return `<section class="card"><div class="card-head"><div><h2>Разбор плана</h2><p>Узкие места, заимствования и спрос на следующий спринт — из расчёта ядра.</p></div><div class="button-row"><button class="btn" data-action="scenarios">Стресс-сценарии</button><button class="btn" data-action="explain">Подробный разбор</button></div></div>`+
 (e?`<p>Точный план: <strong>${e.exact.initiatives_done}</strong> ${plural(e.exact.initiatives_done,'инициатива','инициативы','инициатив')} и ${e.exact.tasks_included} ${plural(e.exact.tasks_included,'задача','задачи','задач')} в квартале. Жадный план по тем же условиям: ${e.greedy.initiatives_done} ${plural(e.greedy.initiatives_done,'инициатива','инициативы','инициатив')} и ${e.greedy.tasks_included} ${plural(e.greedy.tasks_included,'задача','задачи','задач')}${e.exact.initiatives_done>e.greedy.initiatives_done?` — точная модель спасает ещё ${e.exact.initiatives_done-e.greedy.initiatives_done}`:''}.</p>`:'')+
 (state.engine?.stability?'<p class="small muted">План пересчитан со стабильностью: оставшаяся работа разложена как можно ближе к прежнему плану, без лишних перестановок.</p>':'')+
 `<details open><summary>Узкие места (${bottlenecks.length})</summary><p class="small muted">Ограничения, выбранные на 100 %: очки команды или часы роли в спринте.</p>${simpleTable(['Спринт','Что','Запланировано','Ёмкость'],bottlenecks.map(b=>`<tr><td>${b.sprint}</td><td>${esc(b.key+(b.kind==='team_sp'?' · SP':' · часы'))}</td><td class="num">${fmt(b.planned)}</td><td class="num">${fmt(b.capacity)}</td></tr>`))}</details>`+
 `<details><summary>Заимствования (${(a.borrowing||[]).length})</summary><p class="small muted">Часы роли сверх фонда своей команды, взятые у организации за квартал. Основа заявок на помощь.</p>${simpleTable(['Команда','Роль','Часов'],(a.borrowing||[]).map(r=>`<tr><td>${esc(r.team)}</td><td>${esc(r.role)}</td><td class="num">${fmt(r.hours)}</td></tr>`))}</details>`+
 `<details><summary>Спрос на следующий спринт (${(a.demand||[]).length})</summary><p class="small muted">Часы задач, готовых к работе, план спринта и фонд роли. Готовых работ больше фонда — это очередь, а не дефицит: дефицит (оранжевый риск) — когда роль занята полностью, а готовая работа ждёт.</p>${simpleTable(['Спринт','Роль','Готово работ, ч','По плану, ч','Фонд, ч'],(a.demand||[]).map(r=>`<tr><td>${r.sprint}</td><td>${esc(r.role)}</td><td class="num">${fmt(r.ready_hours)}</td><td class="num">${fmt(r.planned_hours)}</td><td class="num">${fmt(r.fund_hours)}</td></tr>`))}</details>`+
 `<div id="scenario-result" class="preview-result" aria-live="polite"></div><div id="explain-result" class="preview-result" aria-live="polite"></div></section>`}
function scenarioMarkup(r){
 return `<div class="notice"><strong>Стресс-сценарии</strong><p>Тот же квартал при других допущениях. Сейчас в квартале завершается ${r.base_done} ${plural(r.base_done,'инициатива','инициативы','инициатив')}. План проекта не меняется.</p></div>${r.scenarios.map(s=>s.error?`<p class="notice error">${esc(s.title)}: ${esc(s.error)}</p>`:`<details><summary>${esc(s.title)}: ${s.initiatives_done} из ${s.initiatives_total} инициатив, ${s.tasks_included} из ${s.tasks_total} задач в квартале</summary><p class="small muted">${esc(s.note)}</p>${s.lost.length?`<p>Выпадают: ${s.lost.map(esc).join(', ')}</p>`:''}${s.initiatives.length?`<h3>Цели вне квартала</h3><ul class="risk-list">${s.initiatives.map(i=>`<li><strong>${esc(i.id)}</strong> · rung ${fmt(i.rung,0)}<p>${esc(i.reason)}</p></li>`).join('')}</ul>`:''}${s.tasks.length?`<h3>Что перенести или отменить</h3><ul class="risk-list">${s.tasks.slice(0,40).map(t=>`<li>${subjectLink(t.id)} ${badge(decisionNames[t.decision]||t.status,t.decision==='cancel'?'red':'orange')}<p>${esc(t.reason)}</p></li>`).join('')}</ul>`:''}</details>`).join('')}`}
function explainMarkup(r){const items=[...r.initiatives.map(i=>({id:i.id,head:i.done?'Инициатива завершается':'Инициатива не завершается в квартале',text:i.reason||''})),...r.tasks.map(t=>({id:t.id,head:({included:'В квартале',postponed:'Перенесена',cancelled:'Отменена'})[t.status]||t.status,text:t.reason||''}))];
 return `<div class="notice"><strong>Что будет, если…</strong><p>Контрфакты: модель пересчитана с принудительным включением отложенной работы или спасением инициативы, по текущим условиям.</p></div>${items.length?`<ul class="risk-list">${items.map(i=>`<li>${subjectLink(i.id)} · ${esc(i.head)}<p>${esc(i.text)}</p></li>`).join('')}</ul>`:'<p class="muted">Отложенных работ и сорванных инициатив нет — разбирать нечего.</p>'}`}
function singleRoleNotice(p){const rows=(state.role_bf||[]).filter(r=>r.bf===1&&r.holders.includes(p.id)&&r.demand_hours>0);if(!rows.length)return '';const tasks=new Set(rows.flatMap(r=>r.tasks)),goals=new Set(rows.flatMap(r=>r.goals_at_risk));
 return `<div class="notice warning"><strong>Единственный носитель роли: ${esc(rows.map(r=>r.role).join(', '))}</strong><p>Другого исполнителя в организации нет: без этого человека встают ${tasks.size} ${plural(tasks.size,'задача','задачи','задач')}${goals.size?` и ${goals.size} ${plural(goals.size,'цель','цели','целей')} квартала: ${esc([...goals].join(', '))}`:''}.</p></div>`}
function roleMapMarkup(){const rows=state.role_bf||[];if(!rows.length)return '';const single=rows.filter(r=>r.bf===1&&r.demand_hours>0),missing=rows.filter(r=>r.bf===0);
 return `<h2>Роли: кто закрывает работы</h2><p class="small muted">Bus Factor роли — сколько разных людей её закрывают. Часы сметы задачи может выполнить только носитель роли, поэтому при BF = 1 без одного человека встают все работы роли.</p><div class="pill-list">${badge('Ролей с одним носителем: '+single.length,'red')}${badge('Ролей вне штата: '+missing.length,'orange')}</div><div class="table-wrap"><table class="table"><thead><tr><th>Роль</th><th>BF</th><th>Носители</th><th>Часов в спринт</th><th>Спрос, ч</th><th>Задач</th><th>Цели под угрозой без носителя</th><th></th></tr></thead><tbody>${rows.filter(r=>r.demand_hours>0||r.bf<=1).map(r=>`<tr><td>${esc(r.role)}</td><td>${badge(r.bf,r.bf===0?'orange':r.bf===1?'red':r.bf===2?'yellow':'green')}</td><td>${r.holders.map(id=>`<button class="text-button" data-person="${esc(id)}">${esc(personName(id))}</button>`).join(', ')||'нет в штате'}</td><td class="num">${fmt(r.available_hours)}</td><td class="num">${fmt(r.demand_hours,0)}</td><td class="num">${r.tasks.length}</td><td>${r.bf===1?(r.goals_at_risk.length?`${r.goals_at_risk.length}: ${r.goals_at_risk.map(esc).join(', ')}`:'—'):r.bf===0?'работа вне штата':'—'}</td><td>${r.bf===1?`<button class="btn small" data-whatif="${esc(r.holders[0])}">Проверить</button>`:''}</td></tr>`).join('')}</tbody></table></div><p class="small muted">Спрос — остаток часов роли в открытых задачах. «Проверить» пересчитывает план так, будто носитель недоступен, и показывает, какие цели уйдут за квартал. Ничего не сохраняется.</p>`}
function bfMethod(){return `<details class="glossary"><summary>Как считается Bus Factor</summary><ul class="risk-list">
<li><strong>Роли.</strong> BF роли — число разных людей, у которых роль есть в профиле; совместитель нескольких команд считается один раз. Смета задачи задана в часах ролей, выполнить их может только носитель роли. Поэтому при BF = 1 без этого человека встают все работы роли, а цели с такими работами — под угрозой.</li>
<li><strong>Технологии.</strong> BF технологии — число людей, указавших её в заявленном стеке (skills_declared), по организации и внутри каждой команды. BF = 1 — знание в одной голове, даже если роль есть у нескольких.</li>
<li><strong>Уникальные профили.</strong> DBSCAN по наборам технологий: профили похожи, если косинусная близость наборов не ниже 0,4. Человек без похожих коллег — уникальный профиль.</li>
<li><strong>Доступность.</strong> Часы в спринт — доля ставки × 80 ч с учётом отпусков, болезни и согласованной помощи.</li>
<li><strong>Проверка отсутствия.</strong> Кнопка «Что будет без сотрудника» пересчитывает план ядром так, будто человек недоступен в выбранных спринтах, и показывает сдвиги и цели, ушедшие за квартал.</li></ul></details>`}
function sprintOptions(first,last,selected){let html='';for(let s=first;s<=last;s++)html+=`<option value="${s}" ${s===selected?'selected':''}>Спринт ${s}</option>`;return html}
function whatIfDialog(id){const p=state.people.find(p=>p.id===id);if(!p)return;const first=state.cutoff+1,last=quarter();
 if(first>last){toast('Квартал завершён: проверять нечего',true);return}
 showDialog(drawerHead('Что будет без сотрудника',personLabel(p))+`<p class="small muted">План пересчитывается так, будто ${esc(p.id)} недоступен в выбранных спринтах: его часы уходят из фонда ролей. Ничего не сохраняется.</p>${singleRoleNotice(p)}<form id="whatif-form" data-person="${esc(id)}"><div class="form-grid"><div class="field"><label for="whatif-from">Со спринта</label><select id="whatif-from" name="from">${sprintOptions(first,last,first)}</select></div><div class="field"><label for="whatif-to">По спринт включительно</label><select id="whatif-to" name="to">${sprintOptions(first,last,Math.min(first,last))}</select></div></div><div class="form-actions"><button class="btn primary" type="submit">Проверить</button></div></form><div id="whatif-result" class="preview-result" aria-live="polite"></div>`)}
function whatIfMarkup(r){const lost=Object.values(r.lost||{}).reduce((a,b)=>a+b,0);return `<div class="notice ${r.goals_lost.length?'warning':''}"><strong>${esc(r.engineer_id)} недоступен в спринтах ${r.from_sprint}–${r.to_sprint}</strong><p>Потеря: ${fmt(lost)} ч. В квартале завершается ${r.goals_kept} из ${r.goals_total} инициатив${r.goals_lost.length?`; за квартал уходят: ${r.goals_lost.map(esc).join(', ')}`:' — прежние цели сохраняются'}.</p></div>${r.initiatives.map(i=>`<p><strong>${esc(i.id)}</strong> — ${esc(i.reason)}</p>`).join('')}${changesMarkup(r.changes)}`}
function orgMapMarkup(){const o=state.star;if(!o)return '';const critical=o.bus_factor.filter(r=>r.bf===1),scarce=o.bus_factor.filter(r=>r.bf===2);
 const rows=list=>simpleTable(['Технология','BF','Носители'],list.map(r=>`<tr><td>${esc(r.skill)}</td><td>${badge(r.bf,r.bf===1?'red':'orange')}</td><td>${r.holders.map(id=>`<button class="text-button" data-person="${esc(id)}">${esc(personName(id))}</button>`).join(', ')}</td></tr>`));
 return `<h2>Вся организация</h2><p class="small muted">Bus Factor по организации — сколько разных людей владеют технологией; совместитель считается один раз. Всего технологий: ${o.bus_factor.length}.</p><div class="pill-list">${badge('BF = 1: '+critical.length,'red')}${badge('BF = 2: '+scarce.length,'orange')}${badge('Уникальных профилей: '+o.unique.length,'purple')}</div><details><summary>Критические технологии — один носитель (${critical.length})</summary>${rows(critical)}</details><details><summary>Дефицитные технологии — два носителя (${scarce.length})</summary>${rows(scarce)}</details><details><summary>Уникальные профили (${o.unique.length})</summary><p class="small muted">Кластеризация DBSCAN по стеку: у этих людей нет коллеги с похожим набором технологий (косинусная близость наборов ниже 0,4) — их трудно подменить целиком.</p><div class="pill-list">${o.unique.map(id=>`<button class="text-button" data-person="${esc(id)}">${esc(personName(id))}</button>`).join(' · ')}</div></details>`}
function riskCounts(risks){const c={red:0,yellow:0,orange:0};(risks||[]).forEach(r=>{if(r.level in c)c[r.level]++});return c}
function previewMarkup(result){const c=riskCounts(result.risks),severe=c.red+c.yellow,moved=result.changes.filter(x=>(x.kind||'schedule')==='schedule').length;return `<div class="notice ${severe?'warning':''}"><strong>Проверка последствий</strong><p>Сдвигов сроков: ${moved} · в полученном прогнозе ${c.red} красных, ${c.yellow} жёлтых и ${c.orange} оранжевых рисков.</p>${(result.risks||[]).filter(r=>r.level!=='orange').slice(0,3).map(r=>`<p>${esc(r.text||'')}</p>`).join('')}${result.entry?`<p>Выбранная задача: ${esc(endText(result.entry))}. ${esc(result.entry.reasons[0]||'')}</p>`:''}</div>${changesMarkup(result.changes)}`}
function proposalForm(selectedTask=''){
 const others=state.teams.filter(t=>t!==user.team),target=others[0]||'',own=pendingTasks();
 return `<form id="proposal-form"><label for="proposal-kind">Что согласовать</label><select id="proposal-kind" name="kind"><option value="transfer" ${proposalKind==='transfer'?'selected':''}>Передача задачи</option><option value="exchange" ${proposalKind==='exchange'?'selected':''}>Обмен задачами</option><option value="help" ${proposalKind==='help'?'selected':''}>Помощь сотрудника (часы)</option></select>${proposalKind==='help'?`<div class="form-grid"><div class="field"><label for="from-team">Из команды</label><select id="from-team" name="from_team">${teamOptions(user.team)}</select></div><div class="field"><label for="to-team">В команду</label><select id="to-team" name="to_team">${teamOptions(target)}</select></div><div class="field full"><label for="helper-person">Сотрудник</label><select id="helper-person" name="engineer">${state.people.filter(p=>p.allocations[user.team]>0).map(p=>`<option value="${esc(p.id)}">${esc(personLabel(p))} · ${esc(p.roles.join(', '))}</option>`).join('')}</select></div><div class="field"><label>Часы за спринт</label><input name="hours" type="number" min="0.1" max="${fullHours()}" step="0.1" value="16" required></div><div class="field"><label>Начиная со спринта</label><input name="start" type="number" min="${state.cutoff+1}" max="${horizon()}" value="${state.cutoff+1}" required></div><div class="field"><label>По спринт включительно</label><input name="end" type="number" min="${state.cutoff+1}" max="${horizon()}" value="${quarter()}" required></div></div>`:`<label for="transfer-task">Задача вашей команды</label><select id="transfer-task" name="task_id" required>${taskOptions(own,selectedTask)}</select><label for="to-team">Принимающая команда</label><select id="to-team" name="to_team">${others.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('')}</select>${proposalKind==='exchange'?`<label for="other-task">Задача принимающей команды</label><select id="other-task" name="other_task_id" required>${taskOptions(state.tasks.filter(t=>t.team===target&&t.status!=='Done'))}</select>`:''}`}
 <label for="proposal-comment">Комментарий для другой главы</label><textarea id="proposal-comment" name="comment" rows="2" maxlength="1000"></textarea><div id="proposal-preview" class="preview-result" aria-live="polite"></div><div class="form-actions"><button class="btn" type="button" data-action="proposal-preview">Проверить риски</button><button class="btn primary" type="submit">Отправить на согласование</button></div></form>`;
}
function requestsView(){if(!isAdmin())return '';return head('Согласования','Передача, обмен и помощь вступают в силу после согласия глав обеих команд.')+`<section class="card"><h2>Новая заявка</h2><div id="proposal-form-container">${proposalForm()}</div></section><section class="card"><div class="card-head"><h2>Заявки вашей команды</h2>${badge(state.requests.filter(r=>r.status==='pending').length+' ожидают')}</div>${state.requests.slice().reverse().map(r=>`<article class="request"><div class="request-head"><strong>${esc(({transfer:'Передача задачи',exchange:'Обмен задачами',help:'Помощь сотрудника'})[r.kind])}</strong>${badge(({pending:'Ожидает согласования',approved:'Применено',rejected:'Отклонено'})[r.status],r.status==='approved'?'green':r.status==='rejected'?'red':'orange')}</div><p>${esc(r.teams.join(' ↔ '))} · ${esc(r.payload.task_id||r.payload.engineer)}${r.payload.other_task_id?' ↔ '+esc(r.payload.other_task_id):''}${r.kind==='help'?` · ${fmt(r.payload.hours)} ч, С${r.payload.start}–С${r.payload.end}`:''}</p>${r.comment?`<p>${esc(r.comment)}</p>`:''}<p>Согласие: ${esc(r.approvals.join(', '))}. Автор: ${esc(r.author)}.</p><details><summary>Последствия для плана</summary>${previewMarkup(r.preview)}</details>${r.status==='pending'?`<div class="button-row">${r.stale?`<button class="btn" data-decision="refresh" data-request="${r.id}">Обновить расчёт и согласия</button>`:!r.approvals.includes(user.team)?`<button class="btn primary" data-decision="approve" data-request="${r.id}">Согласовать</button>`:badge('Ожидаем вторую главу')}<button class="btn danger" data-decision="reject" data-request="${r.id}">Отклонить</button></div>${r.stale?'<p>План изменился. Перед применением нужен новый расчёт и согласия обеих глав.</p>':''}`:''}</article>`).join('')||empty('Заявок пока нет')}</section>`}
function formValues(form){return Object.fromEntries(new FormData(form).entries())}
function taskPayload(){const form=$('#task-form'),v=formValues(form),remaining_hours={},assignments={},required_skills={};form.querySelectorAll('[data-role-row]').forEach(row=>{const role=row.querySelector('[data-role]').value,h=Number(row.querySelector('[data-hours]').value),eid=row.querySelector('[data-assignee]').value;remaining_hours[role]=h;if(eid)assignments[role]=eid;const skills=row.querySelector('[data-skills]').value.split(',').map(s=>s.trim()).filter(Boolean);if(skills.length)required_skills[role]=skills});return {task_id:form.dataset.taskId,changes:{priority:Number(v.priority),remaining_sp:Number(v.remaining_sp),remaining_hours,assignments,required_skills,not_before:Number(v.not_before)}}}
function proposalPayload(){const v=formValues($('#proposal-form'));const proposal=v.kind==='help'?{kind:v.kind,from_team:v.from_team,to_team:v.to_team,engineer:v.engineer,hours:Number(v.hours),start:Number(v.start),end:Number(v.end)}:{kind:v.kind,task_id:v.task_id,to_team:v.to_team,...(v.kind==='exchange'?{other_task_id:v.other_task_id}:{})};return {proposal,comment:v.comment}}
function collectFact(){const form=$('#fact-form'),v=formValues(form);return {sprint:state.cutoff+1,achieved_sp:Number(v.achieved_sp),note:v.note,tasks:[...form.querySelectorAll('[data-fact-task]')].map(row=>{const remaining_hours={},spent_hours={};row.querySelectorAll('[data-fact-role]').forEach(r=>{const leftText=r.querySelector('[data-left]').value,spent=Number(r.querySelector('[data-spent]').value);if(leftText!=='')remaining_hours[r.dataset.factRole]=Number(leftText);if(spent)spent_hours[r.dataset.factRole]=spent});return {task_id:row.dataset.factTask,status:row.querySelector('[data-status]').value,remaining_sp:(v=>v===''?null:Number(v))(row.querySelector('[data-remaining-sp]').value),remaining_hours:Object.keys(remaining_hours).length?remaining_hours:null,spent_hours}})}}
document.addEventListener('click',async event=>{
 const el=event.target.closest('button,a,[data-node]');if(!el)return;
 if(el.closest('[data-node]')&&Date.now()<suppressClickUntil){event.preventDefault();return}
 try{
  if(el.dataset.authMode){authMode=el.dataset.authMode;renderAuth();return}
  if(el.dataset.page){if(!user){authMode='login';renderAuth();return}closeDialog();page=el.dataset.page;searchText='';teamFilter=page==='plan'?user.team:'';onlyMine=false;render();return}
  if(el.dataset.task){taskDialog(el.dataset.task);return}
  if(el.dataset.whatif){whatIfDialog(el.dataset.whatif);return}
  if(el.dataset.person){personDialog(el.dataset.person);return}
  if(el.dataset.absenceRemove){el.disabled=true;await mutate('/api/employees/absence/delete',{absence_id:el.dataset.absenceRemove},'Отсутствие отменено. План пересчитан.');return}
  if(el.dataset.team){teamDialog(el.dataset.team);return}
  if(el.dataset.mapMode){mapMode=el.dataset.mapMode;render();return}
  if(el.dataset.transferTask){closeDialog();page='requests';proposalKind='transfer';render();$('#transfer-task').value=el.dataset.transferTask;return}
  if(el.dataset.invite){el.disabled=true;const r=await api('/api/invitations',base({engineer_id:el.dataset.invite}));showDialog(drawerHead('Приглашение сотрудника',`${personName(r.engineer_id)} · ${r.team}`)+`<p>Передайте этот одноразовый код сотруднику для регистрации. Он действует ${r.expires_days} дней.</p><code class="invitation-code">${esc(r.code)}</code><p class="small muted">Повторная выдача приглашения отменяет предыдущий неиспользованный код.</p>`);return}
  if(el.dataset.decision){el.disabled=true;await mutate('/api/requests/decide',{request_id:el.dataset.request,decision:el.dataset.decision});return}
  const a=el.dataset.action;if(!a)return;
  if(a==='close')return closeDialog();
  if(a==='theme')return toggleTheme();
  if(a==='new-employee')return newEmployeeDialog();
  if(a==='new-task')return newTaskDialog();
  if(a==='add-role'){$('#new-roles').insertAdjacentHTML('beforeend',newRoleRow());return}
  if(a==='add-employee-role'){$('#employee-role-list').insertAdjacentHTML('beforeend',employeeRoleRow());return}
  if(a==='remove-employee-role'){if($('#employee-role-list').children.length>1)el.closest('[data-employee-role]').remove();return}
  if(a==='remove-role'){if($('#new-roles').children.length>1)el.closest('[data-new-role]').remove();return}
  if(a==='import-facts'){$('#csv-input').click();return}
  if(a==='upload-dataset'){datasetTarget=el.dataset.sprint||'';$('#dataset-input').click();return}
  if(a==='reset-map'){prefs.set('orbita-map-'+state.project_id,'{}');graphView=[0,0,1000,650];render();return}
  if(a==='absence-preview'){if(!$('#absence-form').reportValidity())return;el.disabled=true;const r=await api('/api/employees/absence',base({...absencePayload(),preview:true}));$('#absence-preview').innerHTML=`<div class="notice"><strong>Потеря часов</strong><p>${Object.entries(r.lost).map(([s,h])=>`спринт ${s}: −${fmt(h)} ч`).join(', ')}</p></div>`+previewMarkup(r);return}
  if(a==='task-preview'){if(!$('#task-form').reportValidity())return;el.disabled=true;const r=await api('/api/tasks/update',base({...taskPayload(),preview:true}));$('#task-preview').innerHTML=previewMarkup(r);return}
  if(a==='proposal-preview'){if(!$('#proposal-form').reportValidity())return;el.disabled=true;const r=await api('/api/requests/create',base({...proposalPayload(),preview:true}));$('#proposal-preview').innerHTML=previewMarkup(r);return}
  el.disabled=true;
  if(a==='refresh'){await refresh();toast('Данные обновлены')}
  if(a==='approve'){await mutate('/api/approve');toast(state.baseline?'Исходный план зафиксирован. Можно внести факт.':'Согласие сохранено. Ожидаем остальных глав.')}
  if(a==='replan')await mutate('/api/replan');
  if(a==='close-sprint')await mutate('/api/sprint/close',{sprint:Number(el.dataset.sprint)},'Итоговый пересчёт выполнен. Итоги спринта — в разделе «Факт и пересчёт».');
  if(a==='explain'){const r=await api('/api/explain',{});$('#explain-result').innerHTML=explainMarkup(r)}
  if(a==='scenarios'){const r=await api('/api/scenarios',{});$('#scenario-result').innerHTML=scenarioMarkup(r)}
  if(a==='logout'){await api('/api/auth/logout',{});user=null;state=null;csrf='';factDraft=null;closeDialog();renderAuth()}
 }catch(error){toast(error.message,true)}finally{el.disabled=false}
});
document.addEventListener('change',async event=>{
 const el=event.target;
 try{
  if(el.matches('[data-role-select]')){const input=el.parentElement.querySelector('[data-role-new]'),fresh=el.value==='__new';input.hidden=!fresh;input.required=fresh;if(fresh)input.focus()}
  if(el.id==='team-filter'){teamFilter=el.value;render()}
  if(el.id==='only-mine'){onlyMine=el.checked;$('#task-table').innerHTML=taskTable(filteredTasks())}
  if(el.id==='proposal-kind'){proposalKind=el.value;$('#proposal-form-container').innerHTML=proposalForm()}
  if(el.id==='to-team'&&$('#other-task'))$('#other-task').innerHTML=taskOptions(state.tasks.filter(t=>t.team===el.value&&t.status!=='Done'));
  if(el.id==='from-team')$('#helper-person').innerHTML=state.people.filter(p=>p.allocations[el.value]>0).map(p=>`<option value="${esc(p.id)}">${esc(personLabel(p))} · ${esc(p.roles.join(', '))}</option>`).join('');
  if(el.matches('[data-status]')){
   const row=el.closest('[data-fact-task]'),fields=[row.querySelector('[data-remaining-sp]'),...row.querySelectorAll('[data-left]')];
   if(el.value==='Done')fields.forEach(input=>{input.dataset.previous=input.value;input.value=0;input.readOnly=true});
   else fields.forEach(input=>{input.readOnly=false;if(input.dataset.previous!==undefined){input.value=input.dataset.previous;delete input.dataset.previous}});
  }
  if(el.id==='dataset-input'&&el.files[0]){const file=el.files[0];if(file.size>2000000)throw new Error('Максимальный размер датасета — 2 МБ');state=await api('/api/dataset/upload',await file.arrayBuffer(),'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',{'X-Revision':String(state.revision),...(datasetTarget?{'X-Sprint':datasetTarget}:{})});user=state.user;page='facts';render();toast('Датасет загружен. План не пересчитан: проверьте изменения и запустите пересчёт.');el.value=''}
  if(el.id==='csv-input'&&el.files[0]){const file=el.files[0];if(file.size>2000000)throw new Error('Максимальный размер CSV — 2 МБ');const r=await api('/api/facts/parse-csv',await file.arrayBuffer(),true);factDraft=r.report;page='facts';render();toast('CSV загружен в форму. Проверьте значения и подтвердите факт.');el.value=''}
 }catch(error){toast(error.message,true);if(el.type==='file')el.value=''}
});
document.addEventListener('input',event=>{if(event.target.id==='search'){searchText=event.target.value;$('#task-table').innerHTML=taskTable(filteredTasks())}});
document.addEventListener('submit',async event=>{
 event.preventDefault();const form=event.target,button=event.submitter||form.querySelector('button[type="submit"]');if(button)button.disabled=true;
 try{
  const v=formValues(form);
  if(form.id==='auth-form'){const r=await api('/api/auth/'+authMode,v);user=r.user;csrf=r.csrf;page='overview';teamFilter='';await refresh();return}
  if(form.id==='task-form')await mutate('/api/tasks/update',taskPayload());
  if(form.id==='employee-form'){const roles=[...new Set([...form.querySelectorAll('[data-employee-role]')].map(pickedRole).filter(Boolean))];if(!roles.length)throw new Error('Выберите хотя бы одну роль');await mutate('/api/employees/add',{name:v.name,grade:v.grade,capacity_rate:Number(v.capacity_rate),roles,skills:v.skills.split('\n').map(s=>s.trim()).filter(Boolean)})}
  if(form.id==='new-task-form'){const hours={};form.querySelectorAll('[data-new-role]').forEach(r=>{const role=pickedRole(r);if(Object.hasOwn(hours,role))throw new Error('Одна роль указана несколько раз');hours[role]=Number(r.querySelector('[data-hours]').value)});await mutate('/api/tasks/add',{...v,sp:Number(v.sp),priority:Number(v.priority),hours,predecessors:v.predecessors.split(',').map(s=>s.trim()).filter(Boolean)})}
  if(form.id==='absence-form')await mutate('/api/employees/absence',absencePayload(),'Отсутствие сохранено. План пересчитан.');
  if(form.id==='availability-form')await mutate('/api/employees/availability',{engineer_id:form.dataset.person,hours:{[state.cutoff+1]:Number(v.hours)}});
  if(form.id==='proposal-form'){await mutate('/api/requests/create',proposalPayload());toast('Заявка отправлена. Ожидаем согласие другой главы.')}
  if(form.id==='whatif-form'){const r=await api('/api/whatif/absence',{engineer_id:form.dataset.person,from_sprint:Number(v.from),to_sprint:Number(v.to)});$('#whatif-result').innerHTML=whatIfMarkup(r)}
  if(form.id==='fact-form')await mutate('/api/facts',{report:collectFact()},'Отчёт команды сохранён. План пересчитает итоговый пересчёт спринта.');
 }catch(error){if(form.id==='auth-form')$('#auth-error').innerHTML=`<div class="notice error">${esc(error.message)}</div>`;else toast(error.message,true)}finally{if(button)button.disabled=false}
});
function mapPoint(event,svg){const p=svg.createSVGPoint();p.x=event.clientX;p.y=event.clientY;return p.matrixTransform(svg.getScreenCTM().inverse())}
function updateGraph(){const svg=$('#star-map');if(!svg)return;const map=new Map(graphNodes.map(n=>[n.id,n]));svg.querySelectorAll('[data-node]').forEach(g=>{const n=map.get(g.dataset.node);g.setAttribute('transform',`translate(${n.x},${n.y})`)});svg.querySelectorAll('[data-from]').forEach(line=>{const a=map.get(line.dataset.from),b=map.get(line.dataset.to);line.setAttribute('x1',a.x);line.setAttribute('y1',a.y);line.setAttribute('x2',b.x);line.setAttribute('y2',b.y)})}
function saveGraph(){prefs.set('orbita-map-'+state.project_id,JSON.stringify(Object.fromEntries(graphNodes.map(n=>[n.id,{x:Math.round(n.x*10)/10,y:Math.round(n.y*10)/10}]))))}
document.addEventListener('pointerdown',event=>{
 const svg=event.target.closest('#star-map');if(!svg||event.button!==0)return;
 const group=event.target.closest('[data-node]'),point=mapPoint(event,svg),node=graphNodes.find(n=>n.id===group?.dataset.node);
 drag={id:node?.id,point,start:node?{x:node.x,y:node.y}:null,view:[...graphView],client:{x:event.clientX,y:event.clientY},moved:false,pointer:event.pointerId};
 svg.setPointerCapture(event.pointerId);svg.classList.add('dragging');event.preventDefault();
});
document.addEventListener('pointermove',event=>{
 if(!drag||drag.pointer!==event.pointerId)return;const svg=$('#star-map');if(!svg)return;
 const moved=Math.hypot(event.clientX-drag.client.x,event.clientY-drag.client.y)>4;drag.moved=drag.moved||moved;
 if(drag.id){const p=mapPoint(event,svg),node=graphNodes.find(n=>n.id===drag.id);node.x=drag.start.x+p.x-drag.point.x;node.y=drag.start.y+p.y-drag.point.y;updateGraph()}
 else{const rect=svg.getBoundingClientRect(),scale=Math.max(drag.view[2]/rect.width,drag.view[3]/rect.height);graphView=[drag.view[0]-(event.clientX-drag.client.x)*scale,drag.view[1]-(event.clientY-drag.client.y)*scale,drag.view[2],drag.view[3]];svg.setAttribute('viewBox',graphView.join(' '))}
});
function endDrag(event){if(!drag||drag.pointer!==event.pointerId)return;const svg=$('#star-map');if(drag.moved){suppressClickUntil=Date.now()+200;if(drag.id)saveGraph()}else if(drag.id){const n=graphNodes.find(n=>n.id===drag.id);if(n.type==='person')personDialog(n.key);else teamDialog(n.key);suppressClickUntil=Date.now()+200}if(svg){svg.classList.remove('dragging');if(svg.hasPointerCapture(event.pointerId))svg.releasePointerCapture(event.pointerId)}drag=null}
document.addEventListener('pointerup',endDrag);
document.addEventListener('pointercancel',event=>{if(drag?.pointer===event.pointerId){drag=null;$('#star-map')?.classList.remove('dragging')}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('#drawer')?.open){event.preventDefault();closeDialog();return}const g=event.target.closest?.('[data-node]');if(!g)return;const n=graphNodes.find(n=>n.id===g.dataset.node);if(event.key==='Enter'||event.key===' '){event.preventDefault();n.type==='person'?personDialog(n.key):teamDialog(n.key)}else if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();n.x+=event.key==='ArrowLeft'?-10:event.key==='ArrowRight'?10:0;n.y+=event.key==='ArrowUp'?-10:event.key==='ArrowDown'?10:0;updateGraph();saveGraph()}});
async function boot(){try{const r=await api('/api/auth/me');user=r.user;csrf=r.csrf;await refresh()}catch(error){renderAuth()}}
boot();
